application.css:
* { box-sizing: border-box; }
:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #5c667a;
  --border: #c9d1df;
  --surface: #ffffff;
  --background: #f3f6fb;
  --primary: #2356a6;
  --primary-dark: #173d79;
  --danger: #a32626;
  --success: #155d3b;
}
body { margin: 0; background: var(--background); color: var(--ink); font-family: system-ui, -apple-system, "Segoe UI", sans-serif; line-height: 1.5; }
.container { width: min(100% - 2rem, 1080px); margin-inline: auto; }
.site-header { background: #172f5f; color: white; padding: 2.5rem 0; }
.eyebrow { margin: 0 0 .35rem; color: #cfe0ff; font-size: .8rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0; font-size: clamp(1.8rem, 4vw, 2.6rem); }
h2 { margin: 0 0 1.2rem; font-size: 1.35rem; }
.intro { margin: .6rem 0 0; color: #e2ebff; }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 1.5rem; padding-block: 2rem; align-items: start; }
.panel { background: var(--surface); border: 1px solid var(--border); border-radius: .75rem; padding: clamp(1.1rem, 3vw, 1.75rem); box-shadow: 0 5px 18px rgba(23, 32, 51, .06); }
.required-note { margin: -0.7rem 0 1.4rem; color: var(--muted); font-size: .9rem; }
.required-note span, label span { color: var(--danger); font-weight: 700; }
.field { margin-bottom: 1rem; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
label { display: block; margin-bottom: .35rem; font-weight: 650; }
input, select { width: 100%; min-height: 2.75rem; padding: .55rem .7rem; border: 1px solid #8995a9; border-radius: .35rem; background: white; color: var(--ink); font: inherit; }
input:focus, select:focus, button:focus-visible { outline: 3px solid #f0b429; outline-offset: 2px; }
input[aria-invalid="true"], select[aria-invalid="true"] { border-color: var(--danger); }
.error { min-height: 1.25rem; margin: .25rem 0 0; color: var(--danger); font-size: .875rem; }
button { border: 0; border-radius: .4rem; cursor: pointer; font: inherit; font-weight: 700; }
.primary-button { width: 100%; margin-top: .35rem; padding: .75rem 1rem; background: var(--primary); color: white; }
.primary-button:hover { background: var(--primary-dark); }
.confirmation { min-height: 1.5rem; margin: 1rem 0 0; color: var(--success); font-weight: 700; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.count { display: grid; place-items: center; min-width: 2rem; min-height: 2rem; border-radius: 999px; background: #e2ebff; color: #173d79; font-weight: 700; }
.booking-list { display: grid; gap: .85rem; }
.empty-state { margin: 0; color: var(--muted); }
.booking { border: 1px solid var(--border); border-left: 4px solid var(--primary); border-radius: .4rem; padding: 1rem; }
.booking.cancelled { border-left-color: #777; opacity: .72; }
.booking h3 { margin: 0 0 .45rem; font-size: 1.05rem; }
.booking p { margin: .25rem 0; color: var(--muted); }
.booking .status { color: var(--success); font-size: .85rem; font-weight: 700; }
.booking.cancelled .status { color: var(--muted); }
.cancel-button { margin-top: .7rem; padding: .5rem .75rem; background: #fff; border: 1px solid var(--danger); color: var(--danger); }
.cancel-button:hover { background: #fff0f0; }
@media (max-width: 700px) { .layout { grid-template-columns: 1fr; padding-block: 1rem; } .form-row { grid-template-columns: 1fr; gap: 0; } }

application.javascript:
const form = document.querySelector('#booking-form');
const list = document.querySelector('[data-testid="booking-list"]');
const emptyState = document.querySelector('#empty-state');
const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
const count = document.querySelector('#booking-count');
const dateInput = document.querySelector('[data-testid="booking-date"]');
let bookings = [];

function getToday() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function setDateMinimum() {
  dateInput.min = getToday();
}

function showError(fieldName, message) {
  const field = document.querySelector(`[name="${fieldName}"]`);
  const error = document.querySelector(`#${fieldName}-error`);
  field.setAttribute('aria-invalid', message ? 'true' : 'false');
  error.textContent = message;
}

function validateBooking(data) {
  const errors = {};
  if (!data.name.trim()) errors.name = 'Enter the customer name.';
  if (!data.email.trim()) errors.email = 'Enter an email address.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)) errors.email = 'Enter a valid email address.';
  if (!data.date) errors.date = 'Choose an appointment date.';
  else if (data.date < getToday()) errors.date = 'Choose today or a future date.';
  if (!data.time) errors.time = 'Choose an appointment time.';
  if (!data.type) errors.type = 'Select an appointment type.';
  ['name', 'email', 'date', 'time', 'type'].forEach((name) => showError(name, errors[name] || ''));
  return Object.keys(errors).length === 0;
}

function formatDate(date) {
  return new Date(`${date}T00:00:00`).toLocaleDateString(undefined, { dateStyle: 'long' });
}

function createBookingElement(booking) {
  const article = document.createElement('article');
  article.className = `booking${booking.cancelled ? ' cancelled' : ''}`;
  article.dataset.testid = 'booking';
  article.dataset.status = booking.cancelled ? 'cancelled' : 'active';
  const heading = document.createElement('h3');
  heading.dataset.testid = 'booking-name-display';
  heading.textContent = booking.name;
  const details = document.createElement('p');
  details.textContent = `${booking.type} · ${formatDate(booking.date)} at ${booking.time}`;
  const email = document.createElement('p');
  email.textContent = booking.email;
  const status = document.createElement('p');
  status.className = 'status';
  status.textContent = booking.cancelled ? 'Cancelled' : 'Active';
  article.append(heading, details, email, status);
  if (!booking.cancelled) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'cancel-button';
    button.dataset.testid = 'booking-cancel';
    button.dataset.id = booking.id;
    button.textContent = 'Cancel booking';
    article.append(button);
  }
  return article;
}

function renderBookings() {
  list.replaceChildren();
  if (bookings.length === 0) list.append(emptyState);
  else bookings.forEach((booking) => list.append(createBookingElement(booking)));
  count.textContent = String(bookings.filter((booking) => !booking.cancelled).length);
}

function handleSubmit(event) {
  event.preventDefault();
  const data = Object.fromEntries(new FormData(form));
  if (!validateBooking(data)) {
    confirmation.textContent = '';
    const firstInvalid = form.querySelector('[aria-invalid="true"]');
    if (firstInvalid) firstInvalid.focus();
    return;
  }
  bookings.push({ ...data, id: `${Date.now()}-${Math.random()}`, cancelled: false });
  renderBookings();
  confirmation.textContent = 'Booking created successfully.';
  form.reset();
  ['name', 'email', 'date', 'time', 'type'].forEach((name) => showError(name, ''));
  dateInput.min = getToday();
}

function handleCancel(event) {
  const button = event.target.closest('[data-testid="booking-cancel"]');
  if (!button) return;
  const booking = bookings.find((item) => item.id === button.dataset.id);
  if (booking) {
    booking.cancelled = true;
    renderBookings();
  }
}

setDateMinimum();
form.addEventListener('submit', handleSubmit);
list.addEventListener('click', handleCancel);
